const kpis = $('Pull KPIs').first().json || [];
const funnel = $('Pull Agent Funnel').first().json || [];
const today = kpis.filter(k => k.d === new Date().toISOString().slice(0,10));
const sumSpend = today.reduce((a,r)=>a+(r.spend_cents||0),0)/100;
const sumLeads = today.reduce((a,r)=>a+(r.leads||0),0);
const sumAppts = today.reduce((a,r)=>a+(r.appts||0),0);
const sumSales = today.reduce((a,r)=>a+(r.sales||0),0);
const cpl = sumLeads>0 ? sumSpend/sumLeads : null;
const cpa = sumAppts>0 ? sumSpend/sumAppts : null;
const cps = sumSales>0 ? sumSpend/sumSales : null;
const topAgents = funnel.slice(0,5).map(a=>`• ${a.full_name}: ${a.sales} sales / ${a.appointments} appt / ${a.contacted} contacted / ${a.leads_assigned} assigned`).join('\n');
const text = `*Medicare Funnel — last 24h*\nSpend: $${sumSpend.toFixed(0)} | Leads: ${sumLeads} | Appts: ${sumAppts} | Sales: ${sumSales}\nCPL: ${cpl?'$'+cpl.toFixed(2):'—'} | CPA: ${cpa?'$'+cpa.toFixed(2):'—'} | CPS: ${cps?'$'+cps.toFixed(2):'—'}\n\n*Top agents (lifetime)*\n${topAgents}`;
return [{json:{text}}];
